import pyomo.environ as pyo

DATA = {
    "centers": [1, 2, 3, 4, 5],
    "stores": [1, 2, 3, 4, 5, 6, 7],
    "opening_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000, 5: 160000,
    },
    "supply_capacity": {
        1: 1576, 2: 1364, 3: 1697, 4: 891, 5: 1755,
    },
    "demand": {
        1: 566, 2: 673, 3: 787, 4: 1000, 5: 715, 6: 413, 7: 641,
    },
    "transport_cost": {
        (1, 1): 5, (1, 2): 2, (1, 3): 3, (1, 4): 3, (1, 5): 3, (1, 6): 5, (1, 7): 4,
        (2, 1): 3, (2, 2): 5, (2, 3): 2, (2, 4): 4, (2, 5): 2, (2, 6): 4, (2, 7): 5,
        (3, 1): 1, (3, 2): 4, (3, 3): 2, (3, 4): 5, (3, 5): 4, (3, 6): 1, (3, 7): 1,
        (4, 1): 3, (4, 2): 3, (4, 3): 2, (4, 4): 4, (4, 5): 4, (4, 6): 3, (4, 7): 4,
        (5, 1): 4, (5, 2): 1, (5, 3): 3, (5, 4): 5, (5, 5): 3, (5, 6): 5, (5, 7): 1,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["centers"])   # distribution centers
    model.J = pyo.Set(initialize=d["stores"])    # retail stores
    model.Arc = pyo.Set(
        initialize=[(i, j) for i in d["centers"] for j in d["stores"]],
        dimen=2,
    )

    # Decision variables
    model.y = pyo.Var(model.I, within=pyo.Binary)
    model.x = pyo.Var(model.Arc, within=pyo.NonNegativeIntegers)

    # Objective: minimize opening + transportation cost
    def obj_rule(m):
        return (
            sum(d["opening_cost"][i] * m.y[i] for i in m.I)
            + sum(d["transport_cost"][(i, j)] * m.x[(i, j)] for (i, j) in m.Arc)
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Demand must be fulfilled at each store
    def demand_rule(m, j):
        return sum(m.x[(i, j)] for i in m.I) >= d["demand"][j]

    model.demand = pyo.Constraint(model.J, rule=demand_rule)

    # Supply capacity per open center (also enforces x=0 when y_i=0)
    def capacity_rule(m, i):
        return sum(m.x[(i, j)] for j in m.J) <= d["supply_capacity"][i] * m.y[i]

    model.capacity = pyo.Constraint(model.I, rule=capacity_rule)

    return model


